<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#1e293b;font-size:12px}h1{font-size:26px;color:#0f172a}.head{display:flex;justify-content:space-between;margin-bottom:35px}.brand{font-size:22px;font-weight:bold;color:#2563eb}.box{background:#f8fafc;padding:18px;margin:20px 0}table{width:100%;border-collapse:collapse}th{background:#0f172a;color:#fff;text-align:left;padding:10px}td{padding:11px;border-bottom:1px solid #e2e8f0}.right{text-align:right}.totals{margin-left:auto;width:45%;margin-top:20px}.totals td{border:0}.grand{font-size:16px;font-weight:bold;border-top:2px solid #0f172a!important}</style></head><body><div class="head"><div><div class="brand">ClientFlow</div><p>Gestion de projets & services</p></div><div class="right"><h1>{{ __('app.invoice') }}</h1><strong>{{ $invoice->number }}</strong></div></div><div class="box"><strong>{{ $invoice->client->company ?: $invoice->client->name }}</strong><br>{{ $invoice->client->address }}<br>{{ $invoice->client->email }}</div><p>{{ __('app.issue_date') }}: {{ $invoice->issue_date->format('d/m/Y') }} &nbsp; · &nbsp; {{ __('app.due_date') }}: {{ $invoice->due_date->format('d/m/Y') }}</p><table><thead><tr><th>{{ __('app.description') }}</th><th class="right">{{ __('app.quantity') }}</th><th class="right">{{ __('app.unit_price') }}</th><th class="right">{{ __('app.total') }}</th></tr></thead><tbody>@foreach($invoice->items as $item)<tr><td>{{ $item->description }}</td><td class="right">{{ $item->quantity }}</td><td class="right">{{ number_format($item->unit_price,2) }}</td><td class="right">{{ number_format($item->line_total,2) }} MAD</td></tr>@endforeach</tbody></table><table class="totals"><tr><td>{{ __('app.subtotal') }}</td><td class="right">{{ number_format($invoice->subtotal,2) }} MAD</td></tr><tr><td>{{ __('app.tax_rate') }} ({{ $invoice->tax_rate }}%)</td><td class="right">{{ number_format($invoice->tax_amount,2) }} MAD</td></tr><tr><td class="grand">{{ __('app.total') }}</td><td class="right grand">{{ number_format($invoice->total,2) }} MAD</td></tr></table><div class="box">{{ $invoice->notes }}</div></body></html>
